00, #14306a); color: var(--sf-navy-700, #14306a); cursor: default; }\n.bc__tile-year { font-family: var(--sf-school, 'Schoolbell', 'Caveat', cursive); font-size: 1.5rem; line-height: 1.2; }\n.bc__tile-note { font-size: 0.875rem; }\n.bc__ledge-plank { height: 10px; background: var(--sf-navy-700, #14306a); border-radius: 0 0 4px 4px; }\n.bc__genres .bc__muted, .bc__shelfcard .bc__muted { margin: 0; }\n.bc__spines { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; align-items: end; margin: 0; padding: 0; list-style: none; }\n.bc__book { display: grid; gap: 4px; align-content: center; justify-items: center; text-align: center; min-height: var(--h, 210px); padding: 24px 12px 16px; border-radius: 8px 8px 0 0; text-decoration: none; }\n.bc__book::before { content: ''; width: 60px; height: 4px; border-radius: 2px; background: currentColor; opacity: 0.5; }\n.bc__book:focus-visible { outline: 3px solid var(--sf-focus, #14306a); outline-offset: 2px; }\n.bc__book:hover { filter: brightness(1.08); }\n.bc__book-name { font-family: var(--sf-school, 'Schoolbell', 'Caveat', cursive); font-size: 1.5rem; line-height: 1.2; overflow-wrap: anywhere; }\n.bc__book-count { font-size: 0.875rem; }\n.bc__bookitem--0 .bc__book { --h: 210px; background: var(--sf-navy-700, #14306a); color: #fff; }\n.bc__bookitem--1 .bc__book { --h: 240px; background: var(--sf-blue, #1f6fa8); color: #fff; }\n.bc__bookitem--2 .bc__book { --h: 196px; background: var(--sf-star, #dce6ff); color: var(--sf-navy-700, #14306a); border: 2px solid var(--sf-navy-700, #14306a); border-bottom: 0; }\n.bc__bookitem--3 .bc__book { --h: 226px; background: var(--sf-navy-700, #14306a); color: #fff; }\n.bc__bookitem--4 .bc__book { --h: 204px; background: var(--sf-blue, #1f6fa8); color: #fff; }\n.bc__yearshelf { margin: 32px 0; }\n/* the older rule that spaces every section out must not add to the gaps between the cards */\n.bc section.bc__box { margin: 0; }\n.bc section.bc__genres, .bc section.bc__reviews { margin: 24px 0; }\n@media (min-width: 980px) {\n  .bc__intro { grid-template-columns: 2fr 1fr; }\n  .bc__welcome { grid-template-columns: 380px 1fr; }\n  .bc__grid { grid-template-columns: 1fr 1fr 392px; grid-template-areas: 'theme theme come' 'read next shelf'; }\n  .bc__theme { grid-area: theme; }\n  .bc__comecard { grid-area: come; }\n  .bc__reading { grid-area: read; }\n  .bc__next { grid-area: next; }\n  .bc__shelfcard { grid-area: shelf; }\n}\n/* on a phone the books lie flat in a pile, so the names stay readable */\n@media (max-width: 700px) {\n  .bc__spines { grid-template-columns: 1fr; gap: 0; }\n  .bc__bookitem { margin-left: 0; }\n  .bc__bookitem--1 { margin-left: 14px; }\n  .bc__bookitem--2 { margin-left: 4px; }\n  .bc__bookitem--3 { margin-left: 18px; }\n  .bc__bookitem--4 { margin-left: 8px; }\n  .bc__book { grid-template-columns: 1fr auto; justify-items: start; text-align: left; min-height: 0; padding: 12px 16px; border-radius: 8px 4px 4px 8px; }\n  .bc__book::before { display: none; }\n  .bc__bookitem--2 .bc__book { border-bottom: 2px solid var(--sf-navy-700, #14306a); }\n}\n"
